// Service worker Pegonizer v2.2 — satu file ini juga menyajikan manifest & ikon (file virtual),
// sehingga repositori cukup berisi 2 file: index.html dan sw.js.
const CACHE = 'pegonizer-v2.2';
const SHELL = ['./', 'index.html'];
const MANIFEST = {"name": "Pegonizer", "short_name": "Pegonizer", "description": "Alih aksara Latin ke Pegon, standar al-Qolam '24", "display": "standalone", "start_url": "./", "scope": "./", "background_color": "#0b1220", "theme_color": "#0f5c46", "icons": [{"src": "icons/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"}, {"src": "icons/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"}, {"src": "icons/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"}], "id": "./", "lang": "id"};
const ICONS = {
  'icons/icon-192.png': '',
  'icons/icon-512.png': ''
};
function b64bytes(b){ const s = atob(b), u = new Uint8Array(s.length); for (let i=0;i<s.length;i++) u[i]=s.charCodeAt(i); return u; }

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    if (url.pathname.endsWith('/manifest.webmanifest'))
      return e.respondWith(new Response(JSON.stringify(MANIFEST), { headers: { 'Content-Type': 'application/manifest+json' } }));
    for (const k of Object.keys(ICONS))
      if (url.pathname.endsWith('/' + k)) return e.respondWith(new Response(b64bytes(ICONS[k]), { headers: { 'Content-Type': 'image/png' } }));
  }
  const cdn = url.hostname === 'cdnjs.cloudflare.com';
  if (url.origin !== location.origin && !cdn) return;
  e.respondWith(
    caches.match(req).then(hit => {
      const net = fetch(req).then(res => {
        if (res && (res.ok || res.type === 'opaque')) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
        return res;
      }).catch(() => hit);
      return hit || net;
    })
  );
});
